fn test_2sat_solves_and_refutes() {
    assert answers[0] == "0", "2SAT[1]: this formula is unsatisfiable, got " + answers[0]
    assert verdicts == [true, true], "2SAT: an answer does not satisfy its formula: " + str(verdicts)
