# Return: For each formula, 0 if it cannot be satisfied, or 1 followed by a
# satisfying assignment.

let formulas = [
    { variables: 2, clauses: [[1, 2], [-1, 2], [1, -2], [-1, -2]] },
    { variables: 3, clauses: [[1, 2], [2, 3], [-1, -2], [-2, -3]] },
]

