                    finish_order = push(finish_order, vertex)
                    stack = slice(stack, 0, len(stack) - 1)
                }
            }
        }
    }

    let component = []
    for _ in range(0, size) {
        component = push(component, -1)
    }
    let count = 0
    let position = size - 1
    while position >= 0 {
        let start = finish_order[position]
        if component[start] == -1 {
            component[start] = count
            let stack = [start]
