    let found = false
    let u = 0
    while u < n and found == false {
        let v = u + 1
        while v < n and found == false {
            let shared = 0
            for candidate in neighbours[u] {
                if contains(neighbours[v], candidate) {
                    shared = shared + 1
                }
            }
            if shared >= 2 {
                found = true
            }
            v = v + 1
